with valid as (select *, cast(amount as int) as amount_int from payments where paid_at >= to_date('2023-07-03') and method is null), scored as (select *, first_value(amount_int) ignore nulls over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as first_known_amount_int, lead(amount, 1) over (partition by order_id order by amount, id) as next_amount, last_value(method) ignore nulls over (partition by status order by paid_at, id rows between unbounded preceding and current row) as last_known_method, sum(amount_int) over (partition by order_id) as order_id_sum_amount_int from valid), prev_events as (select *, lag(paid_at) over (partition by order_id order by paid_at, id) as prev_paid_at from scored), gaps as (select *, case when prev_paid_at is null or paid_at > prev_paid_at + interval 30 days then 1 else 0 end as is_new_session from prev_events), sessions_payments as (select *, sum(is_new_session) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as session_id from gaps), base as (select *, to_date(prev_paid_at) as prev_paid_at_date, coalesce(method, 'N/A') as resolved_method from sessions_payments where order_id is not null) select session_id, date_trunc('quarter', prev_paid_at_date) as quarter_start, date_trunc('year', prev_paid_at_date) as year_start, sort_array(collect_set(status)) as status_list, sort_array(collect_set(method)) as method_list, round(sum(order_id_sum_amount_int) / nullif(count(case when method = 'card' then 1 end), 0), 2) as order_id_sum_amount_int_per_card, percentile_approx(amount, 0.95) as amount_p95, count(distinct order_id) as distinct_order_ids from base group by session_id, date_trunc('quarter', prev_paid_at_date), date_trunc('year', prev_paid_at_date) having count(distinct order_id) >= 1 order by distinct_order_ids desc;
